<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';require_once __DIR__.'/csrf_helper.php';require_once __DIR__.'/includes/club_expenses.php';require_once __DIR__.'/includes/ui_shell.php';
require_once __DIR__.'/includes/staff_agenda_lists.php';
staffRequireActivePosition('finance_manager');header('Cache-Control: no-store, private');
function ceH(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function ceMoney(int $n):string{return number_format($n/100,2,',',' ').' Kč';}
function ceMinor(string $s):int{if(!preg_match('/^-?\d{1,10}(?:[.,]\d{1,2})?$/D',$s))throw new ClubExpenseException('Částku zadejte v Kč s nejvýše dvěma desetinnými místy.');$negative=str_starts_with($s,'-');$a=explode('.',str_replace(',','.',ltrim($s,'-')));return ($negative?-1:1)*((int)$a[0]*100+(int)str_pad($a[1]??'',2,'0'));}
function ceStart(string $action):void{?><form method="post" class="border rounded p-3 mb-3"><input type="hidden" name="action" value="<?=ceH($action)?>"><input type="hidden" name="csrf_token" value="<?=ceH(csrf_token())?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(16))?>"><?php }
function ceInput(string $name,string $label,string $type='text',bool $required=true,string $value=''):void{?><label class="d-block mb-2"><?=ceH($label)?><input class="form-control" name="<?=ceH($name)?>" type="<?=ceH($type)?>" <?= $required?'required':''?> value="<?=ceH($value)?>"></label><?php }
function ceEnd():void{ceInput('reason','Důvod zápisu (alespoň 10 znaků)');?><label class="d-block"><input type="checkbox" name="confirmed" value="1" required> Ověřil/a jsem podklady a potvrzuji tento zápis.</label><button class="btn btn-primary mt-2">Uložit</button></form><?php }
function cePerson(string $prefix):void{?><label>Druh osoby<select name="<?=ceH($prefix)?>_kind" class="form-select"><option value="trainer">Pracovník</option><option value="person">Sportovec / člen</option><option value="supplier">Dodavatel (jen výdaj)</option></select></label><?php ceInput($prefix.'_id','ID konkrétní osoby (dodavatel bez ID)','number',false);ceInput($prefix.'_label','Ověřené jméno / označení');}
$error='';if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!csrf_verify((string)($_POST['csrf_token']??'')))throw new ClubExpenseException('Neplatný CSRF token.',403);
 $actor=(int)$_SESSION['trener_id'];$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirmed']??'')==='1';$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);$key=(string)($_POST['request_key']??'');
 if($action==='case')clubExpenseCreateCase($pdo,$_POST,$actor,$reason,$confirmed);
 elseif($action==='claim'){$in=$_POST;$in['amount_minor']=ceMinor((string)($_POST['amount']??''));$in['original_amount_minor']=empty($_POST['original_amount'])?$in['amount_minor']:ceMinor((string)$_POST['original_amount']);$items=[];foreach(preg_split('/\R/u',trim((string)($_POST['items']??''))) as $line){$parts=explode(';',$line,6);if(count($parts)<5||!in_array(trim($parts[1]),['ano','ne'],true))throw new ClubExpenseException('Položky: částka Kč;ano/ne;ID akce nebo 0;činnost;účel.');$items[]=['amount_minor'=>ceMinor(trim($parts[0])),'accepted'=>trim($parts[1])==='ano','case_id'=>(int)trim($parts[2]),'activity'=>trim($parts[3]),'purpose'=>trim($parts[4]),'stock_movement_id'=>(int)trim($parts[5]??'0')];}$in['items']=$items;clubExpenseCreateClaim($pdo,$in,$actor,$reason,$confirmed);}
 elseif($action==='claim_state')clubExpenseClaimTransition($pdo,$id,(string)($_POST['transition']??''),$actor,$reason,$confirmed);
 elseif($action==='advance'){$in=$_POST;$in['limit_minor']=ceMinor((string)($_POST['amount']??''));clubExpenseCreateAdvance($pdo,$in,$actor,$reason,$confirmed);}
 elseif($action==='advance_state')clubExpenseAdvanceTransition($pdo,$id,(string)($_POST['transition']??''),$actor,$reason,$confirmed);
 elseif($action==='allocate')clubExpenseAllocate($pdo,(string)($_POST['case_type']??''),$id,(int)($_POST['movement_id']??0),ceMinor((string)($_POST['amount']??'')),$key,(string)($_POST['effective_on']??''),$actor,$reason,$confirmed,empty($_POST['reverses_id'])?null:(int)$_POST['reverses_id'],empty($_POST['return_of_allocation_id'])?null:(int)$_POST['return_of_allocation_id']);
 elseif($action==='consume')clubExpenseConsume($pdo,$id,(int)($_POST['advance_id']??0),ceMinor((string)($_POST['amount']??'')),$key,(string)($_POST['effective_on']??''),$actor,$reason,$confirmed,empty($_POST['reverses_id'])?null:(int)$_POST['reverses_id']);
 elseif($action==='transfer')clubExpenseTransferAdvance($pdo,$id,(int)($_POST['to_advance_id']??0),ceMinor((string)($_POST['amount']??'')),$key,(string)($_POST['effective_on']??''),(string)($_POST['evidence']??''),$actor,$reason,$confirmed);
 elseif($action==='close_case')clubExpenseCloseCase($pdo,$id,$actor,$reason,$confirmed);
 else throw new ClubExpenseException('Neznámý úkon.');header('Location: club_expenses_admin.php?saved=1',true,303);exit;
}catch(Throwable $e){http_response_code($e instanceof PDOException?500:($e->getCode()===403?403:422));$error=$e instanceof PDOException?'Zápis selhal bez částečné změny.':$e->getMessage();}
$caseList=staffExpenseList($pdo,'case',$_GET);$claimList=staffExpenseList($pdo,'claim',$_GET);$advanceList=staffExpenseList($pdo,'advance',$_GET);
$cases=$caseList['rows'];$claims=$claimList['rows'];$advances=$advanceList['rows'];
?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Výdaje a zálohy</title><?php appUiAssets();?></head><body><?php include __DIR__.'/hlavicka.php';?><main class="container py-4"><h1>Výdaje, zálohy a vyúčtování</h1><p>Hospodář přepíše i osobní nebo papírový požadavek. Každý příjemce je vybrán výslovně. Schválení provádí jiný pověřený hospodář. Skutečné platby doložte v <a href="accounting_ledger_admin.php">peněžní knize</a> a zde přiřaďte jejich pohyb.</p>
<?php if($error):?><div class="alert alert-danger"><?=ceH($error)?></div><?php elseif(isset($_GET['saved'])):?><div class="alert alert-success">Uloženo s auditní stopou.</div><?php endif;?>
<h2>Finanční případy</h2><?php staffListControls($caseList['filters'],$caseList,'Vyúčtování');?><table class="table"><tr><th>Případ</th><th>Vazby / vedoucí</th><th>Termín</th><th>Stav</th></tr><?php foreach($cases as $c):?><tr><td>#<?=(int)$c['id']?> <?=ceH($c['title'])?></td><td>Provozní akce #<?=ceH($c['legacy_event_id'])?> · sportovní akce #<?=ceH($c['club_event_id'])?> · vedoucí #<?=(int)$c['leader_trainer_id']?></td><td><?=ceH($c['due_on'])?></td><td><?=ceH($c['state'])?></td></tr><?php endforeach;?></table>
<details><summary>Založit finanční případ</summary><?php ceStart('case');ceInput('title','Název');ceInput('legacy_event_id','ID původní provozní akce','number',false);ceInput('club_event_id','ID sportovní akce','number',false);ceInput('leader_trainer_id','ID odpovědného vedoucího','number');ceInput('due_on','Termín vyúčtování','date');ceInput('evidence','Podklad propojení a odpovědnosti');ceEnd();?></details>
<h2>Výdaje a závazky</h2><?php staffListControls($claimList['filters'],$claimList,'Datum dokladu');?><p>Včetně původních a opravných verzí. Záporný zůstatek je pohledávka vůči příjemci; doložte skutečný příjem vratky. Uvolnění chybného přídělu samo o sobě není vrácení peněz. Schválené podklady se nepřepisují; opravná verze zachová původní obsah a již doložené úhrady.</p><table class="table"><tr><th>Doklad / verze</th><th>Příjemce / stav</th><th>Celkem / uznáno</th><th>Skutečně vypořádáno / zbývá</th></tr><?php foreach($claims as $c):$b=clubExpenseClaimBalance($pdo,(int)$c['root_id']);?><tr><td>#<?=(int)$c['id']?> / základ #<?=(int)$c['root_id']?> v<?=(int)$c['version_no']?> <?=ceH($c['supplier'].' '.$c['document_number'])?></td><td><?=ceH($c['creditor_label'].' · '.$c['state'])?></td><td><?=ceH(ceMoney((int)$c['amount_minor']).' / '.ceMoney((int)$c['accepted_minor']))?></td><td><?=ceH(ceMoney($b['net_paid_minor']+$b['consumed_minor']).' / '.ceMoney($b['remaining_minor']))?></td></tr><?php endforeach;?></table>
<details><summary>Zapsat výdaj nebo novou opravnou verzi</summary><?php ceStart('claim');ceInput('previous_id','ID předchozí vrácené nebo schválené verze (jen oprava)','number',false);ceInput('case_id','ID finančního případu','number',false);ceInput('receipt_id','ID původní účtenky se soukromou přílohou','number',false);ceInput('supplier','Dodavatel');ceInput('document_number','Číslo dokladu / papírová reference');ceInput('document_on','Datum případu','date');ceInput('due_on','Splatnost','date');ceInput('amount','Celková částka Kč');ceInput('original_currency','Původní měna','text',true,'CZK');ceInput('original_amount','Původní částka (prázdné = částka Kč)','text',false);ceInput('conversion_evidence','Doložený přepočet cizí měny','text',false);?><label>Zdroj úhrady<select name="funding_source" class="form-select"><option value="personal">Vlastní peníze osoby</option><option value="unpaid_supplier">Neuhrazená dodavatelská faktura</option><option value="club">Klubová karta / pokladna</option><option value="advance">Svěřená záloha konkrétní osoby</option></select></label><h3>Skutečný plátce</h3><?php cePerson('payer');?><h3>Věřitel / příjemce proplacení</h3><?php cePerson('creditor');ceInput('payee_evidence','Doložení příjemce a ověřeného způsobu předání');ceInput('purpose','Účel');ceInput('document_evidence','Doložení dokladu / umístění papírového originálu');ceInput('duplicate_review','Prověření případné duplicity','text',false);?><label class="d-block">Položkové rozdělení: částka Kč;ano/ne uznáno;ID případu nebo 0;činnost;účel;volitelně ID skladové příjemky<textarea name="items" required class="form-control" rows="4" placeholder="1000;ano;0;oddíl;Doprava&#10;200;ne;0;osobní;Soukromá část"></textarea></label><?php ceEnd();?></details>
<details><summary>Předložit / schválit / vrátit / zamítnout verzi</summary><?php ceStart('claim_state');ceInput('id','ID konkrétní verze','number');?><select name="transition" class="form-select"><option value="submit">Předložit</option><option value="approve">Schválit</option><option value="return">Vrátit k opravě</option><option value="reject">Zamítnout</option></select><?php ceEnd();?></details>
<h2>Zálohy podle osob</h2><?php staffListControls($advanceList['filters'],$advanceList,'Vyúčtování');?><table class="table"><tr><th>Záloha / příjemce</th><th>Předáno / vráceno</th><th>Čerpáno / převody</th><th>Saldo / stav</th></tr><?php foreach($advances as $a):$b=clubExpenseAdvanceBalance($pdo,(int)$a['id']);?><tr><td>#<?=(int)$a['id']?> <?=ceH($a['recipient_label'])?> · případ #<?=(int)$a['case_id']?></td><td><?=ceH(ceMoney($b['out_minor']).' / '.ceMoney($b['returned_minor']))?></td><td><?=ceH(ceMoney($b['consumed_minor']).' / '.ceMoney($b['transferred_minor']))?></td><td><?=ceH(ceMoney($b['balance_minor']).' · '.$a['state'])?></td></tr><?php endforeach;?></table>
<details><summary>Požádat o zálohu / doplnění další zálohou</summary><?php ceStart('advance');ceInput('case_id','ID finančního případu','number');cePerson('recipient');ceInput('amount','Schvalovaná částka Kč');ceInput('due_on','Termín vyúčtování','date');ceInput('purpose','Účel');ceInput('payee_evidence','Doložení konkrétního příjemce a předání');ceEnd();?></details>
<details><summary>Schválit nebo uzavřít zálohu</summary><?php ceStart('advance_state');ceInput('id','ID zálohy','number');?><select name="transition" class="form-select"><option value="approve">Schválit</option><option value="close">Uzavřít vypořádanou zálohu</option></select><?php ceEnd();?></details>
<details><summary>Přiřadit skutečnou platbu / vratku nebo opravit příděl</summary><?php ceStart('allocate');?><select name="case_type" class="form-select"><option value="expense_claim">Proplacení výdaje (základní ID)</option><option value="expense_claim_return">Skutečný návrat platby / přeplatku výdaje</option><option value="expense_advance_out">Předání zálohy</option><option value="expense_advance_in">Vrácení zálohy</option></select><?php ceInput('id','Základní ID výdaje nebo ID zálohy','number');ceInput('movement_id','ID doloženého pohybu peněžní knihy','number');ceInput('amount','Přidělovaná částka Kč (oprava záporně)');ceInput('effective_on','Skutečné datum přídělu','date');ceInput('reverses_id','Původní ID přídělu při opravě','number',false);ceInput('return_of_allocation_id','ID původního přídělu výplaty při bankovním návratu','number',false);ceEnd();?></details>
