<details><summary>Doložit předání svěřených peněz mezi osobami / akcemi</summary><?php ceStart('transfer');ceInput('id','Ze zálohy ID','number');ceInput('to_advance_id','Na schválenou zálohu ID','number');ceInput('amount','Částka Kč');ceInput('effective_on','Datum skutečného předání','date');ceInput('evidence','Doklad předání mezi příjemci');ceEnd();?></details>
